pub fn start_detached(root: &Path, executable: &Path) -> i32 {
    if super::client::Connection::connect(root).is_ok() {
        print!("{}", status(root));
        return 0;
    }
    match spawn_daemon(root, executable) {
        Ok(pid) => { println!("workspace dashboard daemon ready at pid {pid}"); 0 }
        Err(error) => { eprintln!("failed to start daemon: {error}"); 1 }
    }
}

pub fn start_detached(root: &Path, executable: &Path, text: &DashboardLabels) -> i32 {
    if super::client::Connection::connect(root).is_ok() {
        print!("{}", status(root, text));
        return 0;
    }
    match spawn_daemon(root, executable) {
        Ok(pid) => { println!("{}", text.cli_daemon_ready.fill(&[("pid", &pid.to_string())])); 0 }
        Err(error) => { eprintln!("{}", text.cli_daemon_start_failed.fill(&[("error", &error.to_string())])); 1 }
    }
}
